
$(function () {
  // Admin Panel settings

  //****************************
  /* This is for the mini-sidebar if width is less then 1170*/
  //****************************
  var setsidebartype = function () {
    var width =
      window.innerWidth > 0 ? window.innerWidth : this.screen.width;
    if (width < 1199) {
      $("#main-wrapper").attr("data-sidebartype", "mini-sidebar");
      $("#main-wrapper").addClass("mini-sidebar");
    } else {
      $("#main-wrapper").attr("data-sidebartype", "full");
      $("#main-wrapper").removeClass("mini-sidebar");
    }
  };
  $(window).ready(setsidebartype);
  $(window).on("resize", setsidebartype);
  //****************************
  /* This is for sidebartoggler*/
  //****************************
  $(".sidebartoggler").on("click", function () {
    var $wrapper = $("#main-wrapper");
    var isDesktop = window.innerWidth >= 1200;
    if (isDesktop) {
      $wrapper.toggleClass("sidebar-hidden");
      $wrapper.attr("data-sidebartype", $wrapper.hasClass("sidebar-hidden") ? "mini-sidebar" : "full");
    } else {
      $wrapper.toggleClass("mini-sidebar");
      $wrapper.toggleClass("show-sidebar");
      if ($wrapper.hasClass("mini-sidebar")) {
        $(".sidebartoggler").prop("checked", !0);
        $wrapper.attr("data-sidebartype", "mini-sidebar");
      } else {
        $(".sidebartoggler").prop("checked", !1);
        $wrapper.attr("data-sidebartype", "full");
      }
    }
  });
  // Overlay: inject and click-to-close on mobile
  if ($("#main-wrapper").length && !$("#sidebar-overlay").length) {
    $("#main-wrapper").prepend('<div id="sidebar-overlay" class="sidebar-overlay" aria-hidden="true"></div>');
    $("#sidebar-overlay").on("click", function () {
      $("#main-wrapper").removeClass("show-sidebar").addClass("sidebar-hidden");
      $("#sidebar-overlay").removeClass("active");
    });
    $(document).on("click", ".sidebartoggler", function () {
      setTimeout(function () {
        $("#sidebar-overlay").toggleClass("active", $("#main-wrapper").hasClass("show-sidebar"));
      }, 50);
    });
  }
})